#!/bin/sh
#
# The guest's init for the Termux hostfs gate.
#
# The gate boots the kernel as `init=/um-init` with `rootfstype=hostfs`, so this
# file has to exist inside the hostfs root before the gate runs.  It is not
# generated by any script in this tree -- the gate writes net-command.sh, which
# is the payload, and expects the init that calls it to be part of the root.
# Missing it is reported by the kernel as
#
#	Kernel panic - not syncing: Requested init /um-init failed (error -2)
#
# which reads like a kernel problem and is a missing file in the rootfs.
#
# Keep it minimal: the point of the gate is what net-command.sh observes about
# the network, not what this does.
set +e

mountpoint=/bin/busybox

$mountpoint mount -t proc     proc     /proc 2>/dev/null
$mountpoint mount -t sysfs    sysfs    /sys  2>/dev/null
$mountpoint mount -t devtmpfs devtmpfs /dev  2>/dev/null
# Some applets want /dev/pts and /dev/shm to exist.
mkdir -p /dev/pts /dev/shm /tmp 2>/dev/null
$mountpoint mount -t devpts   devpts   /dev/pts 2>/dev/null
$mountpoint mount -t tmpfs    tmpfs    /dev/shm 2>/dev/null
$mountpoint mount -t tmpfs    tmpfs    /tmp     2>/dev/null

/bin/sh /net-command.sh
rc=$?

# The gate scores this string, and only this string, as the command's verdict.
echo "UM_NET_COMMAND_EXIT=$rc"

$mountpoint poweroff -f 2>/dev/null
# If poweroff did not take, do not fall off the end: init exiting makes the
# kernel panic, which the gate would report as a kernel fault instead of a
# finished run.
while :; do $mountpoint sleep 3600; done
